(217669, 12508, 2170, '<td valign="top">he doesn''t look like he loves you too much right now</td>', 'he doesn''t look like he loves you too much right now', '2003-02-17 17:22:37.000000', NULL, 1),
(217672, 12454, 2170, '<td valign="top">although it''s a nice idea, the expression on the face doesn''t say "love" to me.  it says more like "i wish this guy had washed his hands before we tried to take the picture"</td>', 'although it''s a nice idea, the expression on the face doesn''t say "love" to me.  it says more like "i wish this guy had washed his hands before we tried to take the picture"', '2003-02-17 17:23:36.000000', NULL, 1),
(217674, 12544, 2170, '<td valign="top">The focus on the eye is good, but the lips and fingers are too blurry.  I think this would work better in black and white perhaps, to give it even more drama.</td>', 'The focus on the eye is good, but the lips and fingers are too blurry.  I think this would work better in black and white perhaps, to give it even more drama.', '2003-02-17 17:24:20.000000', NULL, 1),
(217675, 12495, 2170, '<td valign="top">I love the way they pop from the background -- great use of focus.  Too bad about that pile of snow (?) on the right -- otherwise a very lovely image.</td>', 'I love the way they pop from the background -- great use of focus.  Too bad about that pile of snow (?) on the right -- otherwise a very lovely image.', '2003-02-17 17:25:04.000000', NULL, 1),
