(217680, 12543, 2170, '<td valign="top">sad, but true.</td>', 'sad, but true.', '2003-02-17 17:28:24.000000', NULL, 1),
(217684, 12466, 2170, '<td valign="top">lovely and well-done.  my only comment is that the two people should be wearing different color shirts, because this, unfortunately, looks like a two-headed creature.  very nice image, however.</td>', 'lovely and well-done.  my only comment is that the two people should be wearing different color shirts, because this, unfortunately, looks like a two-headed creature.  very nice image, however.', '2003-02-17 17:29:47.000000', NULL, 1),
